CREATE TABLE IF NOT EXISTS gis_phase326_review_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evidence_id uuid REFERENCES gis_geometry_evidence(id) ON DELETE SET NULL, exception_id uuid REFERENCES gis_current_exception_queue(id) ON DELETE SET NULL, reviewer_id text, decision text NOT NULL, previous_state text, new_state text, selected_candidate uuid, rationale text, evidence_version text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_phase326_review_audit_exception ON gis_phase326_review_audit(exception_id,created_at DESC);